        package_data={
            "asc/lib/runtime": ["rt_wrapper.cpp", "npu_utils.cpp", "print_utils.cpp"],
            "asc/lib/host": ["bindings/*.cpp"],
        },
        install_requires=[
            "pybind11==2.10.3",
